package vn.svframe.lively.admin;
import net.fabricmc.fabric.api.event.player.*;import net.minecraft.component.DataComponentTypes;import net.minecraft.item.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.text.Text;import net.minecraft.util.*;import vn.svframe.lively.api.LivelyApi;public final class SelectionWand{private static final String NAME="Lively Selection Wand";private SelectionWand(){}public static void install(){AttackBlockCallback.EVENT.register((player,world,hand,pos,direction)->{if(world.isClient||hand!=Hand.MAIN_HAND||!(player instanceof ServerPlayerEntity server)||!isWand(player.getStackInHand(hand))||!LivelyApi.permissions().has(server.getCommandSource(),"lively.admin.structure",2))return ActionResult.PASS;SelectionService.set(server.getUuid(),true,world.getRegistryKey().getValue().toString(),pos);server.sendMessage(Text.literal("[Lively] pos1 = "+pos.toShortString()),false);return ActionResult.SUCCESS;});UseBlockCallback.EVENT.register((player,world,hand,hit)->{if(world.isClient||hand!=Hand.MAIN_HAND||!(player instanceof ServerPlayerEntity server)||!isWand(player.getStackInHand(hand))||!LivelyApi.permissions().has(server.getCommandSource(),"lively.admin.structure",2))return ActionResult.PASS;SelectionService.set(server.getUuid(),false,world.getRegistryKey().getValue().toString(),hit.getBlockPos());server.sendMessage(Text.literal("[Lively] pos2 = "+hit.getBlockPos().toShortString()),false);return ActionResult.SUCCESS;});}public static ItemStack create(){ItemStack stack=new ItemStack(Items.WOODEN_AXE);stack.set(DataComponentTypes.CUSTOM_NAME,Text.literal(NAME));return stack;}public static boolean isWand(ItemStack stack){if(!stack.isOf(Items.WOODEN_AXE))return false;Text name=stack.get(DataComponentTypes.CUSTOM_NAME);return name!=null&&NAME.equals(name.getString());}}
